      examples: [{ q: "Calculate the pH of 0.0050 mol dm⁻³ NaOH at 298 K.", a: "[OH⁻] = 0.0050; pOH = −log(0.0050) = 2.30; pH = 14.00 − 2.30 = 11.70." }],
